package com.example.employeemanagement.controller;
import com.example.employeemanagement.dto.DepartmentRequest; import com.example.employeemanagement.model.Department; import com.example.employeemanagement.service.DepartmentService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor public class DepartmentController {private final DepartmentService service; @GetMapping public List<Department> all(){return service.all();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Department create(@Valid @RequestBody DepartmentRequest r){return service.save(r);} @PutMapping("/{id}") public Department update(@PathVariable Long id,@Valid @RequestBody DepartmentRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
